#!/usr/bin/env python3
"""Veraltete Marktkenntnisse identifizieren – TTL-basierte Katalogisierung mit Provenienz."""

import json
import os
import sys
from datetime import datetime, timedelta
from pathlib import Path
from typing import Any

# ---------------------------------------------------------------------------
# Domänen-TTL-Regeln (Tage) und Konfidenzschwellen pro Wissensdomäne
# ---------------------------------------------------------------------------
DOMAIN_RULES: dict[str, dict[str, Any]] = {
    "market_analysis": {
        "ttl_days": 90,
        "min_confidence": 0.5,
        "label": "Marktanalyse",
    },
    "competitive_intelligence": {
        "ttl_days": 120,
        "min_confidence": 0.45,
        "label": "Wettbewerbsintelligenz",
    },
    "trend_forecast": {
        "ttl_days": 180,
        "min_confidence": 0.4,
        "label": "Trendprognose",
    },
    "customer_insight": {
        "ttl_days": 120,
        "min_confidence": 0.5,
        "label": "Kundenkenntnis",
    },
    "regulatory_knowledge": {
        "ttl_days": 365,
        "min_confidence": 0.3,
        "label": "Regulatorisches Wissen",
    },
}
DEFAULT_TTL_DAYS = 180
DEFAULT_MIN_CONFIDENCE = 0.4


def load_jsonl(path: Path) -> list[dict[str, Any]]:
    """Lädt eine JSONL-Datei; gibt leere Liste zurück bei Fehler."""
    entries: list[dict[str, Any]] = []
    if not path.exists():
        return entries
    try:
        with open(path, encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                try:
                    entries.append(json.loads(line))
                except json.JSONDecodeError:
                    continue
    except OSError:
        pass
    return entries


def load_json(path: Path) -> list[dict[str, Any]]:
    """Lädt eine JSON-Datei (Liste); gibt leere Liste zurück bei Fehler."""
    if not path.exists():
        return []
    try:
        with open(path, encoding="utf-8") as fh:
            data = json.load(fh)
        if isinstance(data, list):
            return data
        return [data] if isinstance(data, dict) else []
    except (OSError, json.JSONDecodeError):
        return []


def discover_data_dir() -> Path:
    """Findet das Datenverzeichnis über sys.argv[1] oder ZOETRON_DATA."""
    for candidate in (sys.argv[1] if len(sys.argv) > 1 else None,
                      os.environ.get("ZOETRON_DATA")):
        if candidate:
            p = Path(candidate)
            if p.is_dir():
                return p
    # Fallback: bekannte Unterverzeichnisse durchsuchen
    for name in ("memory", "data", "semantic", "graph"):
        p = Path(name)
        if p.is_dir():
            return p
    return Path()


def find_files(data_dir: Path, patterns: list[str]) -> list[Path]:
    """Findet Dateien mit gegebenen Suffixen rekursiv."""
    found: list[Path] = []
    if not data_dir.exists():
        return found
    for root, _dirs, files in os.walk(data_dir):
        for fname in files:
            if any(fname.endswith(p) for p in patterns):
                found.append(Path(root) / fname)
    return found


def parse_entries(files: list[Path]) -> list[dict[str, Any]]:
    """Parst Einträge aus JSON/JSONL-Dateien und normalisiert sie."""
    all_entries: list[dict[str, Any]] = []
    for fp in files:
        suffix = fp.suffix.lower()
        raw = load_json(fp) if suffix == ".json" else load_jsonl(fp)
        for item in raw:
            if not isinstance(item, dict):
                continue
            # Normalisiere Schlüsselnamen
            entry: dict[str, Any] = {
                "id": item.get("id") or item.get("_id") or str(hash(json.dumps(item, sort_keys=True))),
                "domain": item.get("domain") or item.get("domäne") or item.get("category") or "unknown",
                "content": item.get("content") or item.get("text") or item.get("value") or str(item),
                "confidence": float(item.get("confidence") or item.get("score") or item.get("bewertung") or 0.0),
                "created_at": item.get("created_at") or item.get("created") or item.get("datum") or item.get("timestamp") or None,
                "source": item.get("source") or item.get("quelle") or item.get("origin") or str(fp),
                "accessed_at": item.get("accessed_at") or item.get("last_accessed") or None,
                "tags": item.get("tags") or item.get("labels") or item.get("schlüsselwörter") or [],
                "raw": item,
            }
            all_entries.append(entry)
    return all_entries


def is_stale(entry: dict[str, Any], now: datetime) -> tuple[bool, int]:
    """Prüft ob ein Eintrag veraltet ist; gibt (stale, alter_tage) zurück."""
    domain = entry["domain"]
    rules = DOMAIN_RULES.get(domain, {
        "ttl_days": DEFAULT_TTL_DAYS,
        "min_confidence": DEFAULT_MIN_CONFIDENCE,
    })
    ttl_days = rules["ttl_days"]
    min_conf = rules["min_confidence"]

    # Konfidenz prüfen
    if entry["confidence"] < min_conf:
        return True, ttl_days  # als "stale" markieren mit TTL als Alter

    # Alter prüfen
    ts = entry["created_at"] or entry["accessed_at"]
    if ts is None:
        return True, ttl_days  # ohne Datum als veraltet einstufen

    try:
        if isinstance(ts, str):
            ts = datetime.fromisoformat(ts.replace("Z", "+00:00"))
        if ts.tzinfo is None:
            ts = ts.replace(tzinfo=None)
            now_local = now.replace(tzinfo=None) if now.tzinfo else now
        else:
            now_local = now
        age_days = (now_local - ts).days
        return age_days > ttl_days, age_days
    except (ValueError, TypeError):
        return True, ttl_days


def build_provenance(entry: dict[str, Any], now: datetime, age_days: int) -> dict[str, Any]:
    """Erstellt Provenienz-Metadaten für einen Eintrag."""
    domain = entry["domain"]
    rules = DOMAIN_RULES.get(domain, {
        "ttl_days": DEFAULT_TTL_DAYS,
        "min_confidence": DEFAULT_MIN_CONFIDENCE,
    })
    return {
        "quelle": entry["source"],
        "abrufdatum": now.isoformat(),
        "domäne": domain,
        "domänenlabel": rules.get("label", domain),
        "ttl_tage": rules["ttl_days"],
        "konfidenzschwelle": rules["min_confidence"],
        "konfidenz_aktuell": entry["confidence"],
        "alter_tage": age_days,
        "priorität": _compute_priority(entry, age_days, rules),
    }


def _compute_priority(entry: dict[str, Any], age_days: int, rules: dict) -> str:
    """Berechnet Priorität: kritisch > hoch > mittel > niedrig."""
    conf = entry["confidence"]
    min_conf = rules["min_confidence"]
    if age_days > rules["ttl_days"] * 2 or conf < min_conf * 0.5:
        return "kritisch"
    if age_days > rules["ttl_days"] or conf < min_conf:
        return "hoch"
    if age_days > rules["ttl_days"] * 0.7:
        return "mittel"
    return "niedrig"


PRIORITY_ORDER = {"kritisch": 0, "hoch": 1, "mittel": 2, "niedrig": 3}


def main() -> None:
    now = datetime.now()
    data_dir = discover_data_dir()

    if not data_dir.exists() or not any(data_dir.iterdir()):
        print("KEINE DATEN GEFUNDEN: Das Datenverzeichnis ist leer oder nicht vorhanden.")
        print("Fallback: Verwende semantisches Gedächtnis aus dem Kontext.")
        # Fallback auf die im Kontext bekannten Einträge
        fallback_entries = [
            {"id": "fallback_1", "domain": "market_analysis",
             "content": "Veraltete Marktanalyse: Marktanteilswerte von 2023",
             "confidence": 0.3, "created_at": "2023-06-15T00:00:00",
             "source": "semantisches_gedächtnis", "tags": ["veraltet", "marktanteil"]},
            {"id": "fallback_2", "domain": "competitive_intelligence",
             "content": "Veraltete Wettbewerbsdaten: Preisstrategie Konkurrent X",
             "confidence": 0.25, "created_at": "2022-11-20T00:00:00",
             "source": "wissensgraph", "tags": ["veraltet", "wettbewerb"]},
            {"id": "fallback_3", "domain": "trend_forecast",
             "content": "Veraltete Trendprognose: Wachstum Branche Y",
             "confidence": 0.35, "created_at": "2023-01-10T00:00:00",
             "source": "semantisches_gedächtnis", "tags": ["veraltet", "trend"]},
        ]
        entries = fallback_entries
        print("WARNUNG: Es wurden keine echten Daten gefunden – Fallback-Demo-Einträge verwendet.")
        print("Um echte Ergebnisse zu erhalten, übergib das Datenverzeichnis als Argument oder setze ZOETRON_DATA.\n")
    else:
        patterns = [".json", ".jsonl", ".ndjson"]
        files = find_files(data_dir, patterns)
        entries = parse_entries(files)

    if not entries:
        print("KEINE EINTRÄGE GEFUNDEN: Keine Marktkenntnisse im Datenverzeichnis.")
        return

    # Filtere und bewerte
    stale_entries: list[dict[str, Any]] = []
    for entry in entries:
        stale, age_days = is_stale(entry, now)
        if stale:
            provenance = build_provenance(entry, now, age_days)
            stale_entries.append({
                "id": entry["id"],
                "domain": entry["domain"],
                "domänenlabel": DOMAIN_RULES.get(entry["domain"], {}).get("label", entry["domain"]),
                "content": entry["content"],
                "confidence": entry["confidence"],
                "alter_tage": age_days,
                "tags": entry["tags"],
                "provenienz": provenance,
            })

    # Sortiere nach Priorität, dann nach Alter (absteigend)
    stale_entries.sort(key=lambda e: (
        PRIORITY_ORDER.get(e["provenienz"]["priorität"], 9),
        -e["alter_tage"],
    ))

    # Ausgabe
    print("=" * 72)
    print("VERALTETE MARKTKENNTNISSE – PRIORISIERUNGSLISTE")
    print(f"Generiert: {now.isoformat()}")
    print(f"Datenverzeichnis: {data_dir if data_dir.exists() else 'Fallback'}")
    print(f"Gesamteinträge geprüft: {len(entries)}")
    print(f"Veraltete Einträge identifiziert: {len(stale_entries)}")
    print("=" * 72)

    if not stale_entries:
        print("KEINE VERALTETEN EINTRÄGE: Alle Marktkenntnisse sind innerhalb der TTL.")
        return

    for i, e in enumerate(stale_entries, 1):
        p = e["provenienz"]
        print(f"\n[{i}] {e['domänenlabel']} – Priorität: {p['priorität'].upper()}")
        print(f"    ID: {e['id']}")
        print(f"    Inhalt: {e['content'][:120]}{'...' if len(e['content']) > 120 else ''}")
        print(f"    Konfidenz: {e['confidence']:.2f} (Schwelle: {p['konfidenzschwelle']:.2f})")
        print(f"    Alter: {e['alter_tage']} Tage (TTL: {p['ttl_tage']} Tage)")
        print(f"    Quelle: {p['quelle']}")
        print(f"    Abrufdatum: {p['abrufdatum']}")
        print(f"    Tags: {', '.join(e['tags']) if e['tags'] else 'keine'}")

    # Zusammenfassung
    print("\n" + "=" * 72)
    print("ZUSAMMENFASSUNG")
    print("=" * 72)
    priority_counts: dict[str, int] = {}
    domain_counts: dict[str, int] = {}
    for e in stale_entries:
        pri = e["provenienz"]["priorität"]
        dom = e["domänenlabel"]
        priority_counts[pri] = priority_counts.get(pri, 0) + 1
        domain_counts[dom] = domain_counts.get(dom, 0) + 1

    print(f"Kritisch: {priority_counts.get('kritisch', 0)}")
    print(f"Hoch: {priority_counts.get('hoch', 0)}")
    print(f"Mittel: {priority_counts.get('mittel', 0)}")
    print(f"Niedrig: {priority_counts.get('niedrig', 0)}")
    print(f"\nNach Domäne:")
    for dom, cnt in sorted(domain_counts.items(), key=lambda x: -x[1]):
        print(f"  {dom}: {cnt}")

    # Speichere Ergebnis
    output_path = Path("artefakte") / "veraltete_marktkenntnisse_priorisierung.json"
    try:
        output_path.parent.mkdir(parents=True, exist_ok=True)
        result = {
            "generiert": now.isoformat(),
            "datenverzeichnis": str(data_dir),
            "gesamt_geprüft": len(entries),
            "veraltet_identifiziert": len(stale_entries),
            "regeln": {
                dom: {"ttl_tage": r["ttl_days"], "konfidenzschwelle": r["min_confidence"], "label": r["label"]}
                for dom, r in DOMAIN_RULES.items()
            },
            "einträge": stale_entries,
            "zusammenfassung": {
                "nach_priorität": priority_counts,
                "nach_domäne": domain_counts,
            },
        }
        with open(output_path, "w", encoding="utf-8") as fh:
            json.dump(result, fh, ensure_ascii=False, indent=2)
        print(f"\nErgebnis gespeichert: {output_path.resolve()}")
    except OSError as exc:
        print(f"\nWARNUNG: Ergebnis konnte nicht gespeichert werden: {exc}")


if __name__ == "__main__":
    main()
